function flakyClient(failures: Record<string, () => unknown>) {
  const calls: string[] = [];
  const remaining = new Map(
    Object.entries(failures).map(([url, makeErr]) => [
      url,
      { count: Infinity as number, makeErr },
    ]),
  );
  const factory = (ep: LLMEndpoint) =>
    ({
      chat: {
        completions: {
          create: async () => {
            calls.push(ep.baseURL);
            const f = remaining.get(ep.baseURL);
            if (f && f.count > 0) {
              f.count -= 1;
              throw f.makeErr();
            }
            return {
              choices: [
                { message: { content: `translated via ${ep.baseURL}` } },
              ],
            };
          },
        },
      },
    }) as unknown as Pick<OpenAI, 'chat'>;
  return { calls, factory, remaining };
}

